-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "ruRU" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.shaman.elemental.Name"] = "Элементаль"
L["rm.era.shaman.elemental.Description"] = "Стихии с 10 уровня (больше всего очков в «Стихиях»); составлено по Icy Veins и Wowhead. Земной шок прерывает и добивает цель, которая вот-вот умрёт. В движении: Огненный шок, иначе Ледяной шок. В одиночной игре с целью в ближнем бою: Земной шок, пока у цели больше 30% здоровья, затем ближний бой. Против трёх и более врагов: Тотем кольца огня и Тотем магмы, когда вы в ближнем бою, и Цепная молния. Цепная молния под Покорением стихий или при Ясности мысли, иначе Молния. Напоминания: Щит молний, Оружие камнедробителя вне рейдов, Опаляющий тотем или Тотем магмы, Тотем источника маны или Тотем исцеляющего потока, Покорение стихий при готовой Цепной молнии, Природная стремительность и Волна исцеления ниже 30%, лечение после боя. Рассеивание, развеивание и понижение ранга заклинаний остаются за вами."
L["rm.era.shaman.elemental.simulator.Name"] = "Стихии, Цепная молния по готовности (симулятор)"
L["rm.era.shaman.elemental.simulator.Description"] = "Список «Стихий» по симулятор — альтернатива рекомендуемой встроенной ротации «Стихии», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Цепная молния по готовности даже против одной цели, Земной шок, пока действует Покорение стихий, иначе Молния. Быстрее, но расходует намного больше маны, чем рекомендуемая встроенная ротация; прерывание, тотемы и напоминания те же."
L["rm.era.shaman.enhancement.Name"] = "Совершенствование"
L["rm.era.shaman.enhancement.Description"] = "Уровни 1–60, в том числе в игровых мирах «Хардкор» и Self-Found, а также любой шаман без преобладающей ветки талантов; составлено по Icy Veins, Wowhead и симулятор. Начинает бой Молнией с дистанции; Земной шок прерывает. В рейдах только Удар бури и Ледяной шок (места для отрицательных эффектов). Против трёх и более врагов, сражающихся с вами, — Тотем кольца огня и Тотем магмы. Затем Удар бури, Земной шок под отрицательный эффект Удара бури или для добивания, Огненный шок, если он успеет отработать, Земной шок, пока у вас есть половина маны, и Молния, пока цель вне досягаемости. Напоминания: Оружие камнедробителя в одиночной игре и Оружие неистовства ветра в подземельях, Щит молний, Тотем силы земли, Опаляющий тотем, Тотем неистовства ветра или Тотем легкости воздуха, Тотем источника маны или Тотем исцеляющего потока, лечение после боя и в экстренных случаях. Тотем каменного когтя, Тотем оков земли, твист тотемов и расовые способности есть в списке, но выключены; рассеивание, развеивание и очищающие тотемы остаются за вами."
L["rm.era.shaman.enhancement.warcrafttavern.Name"] = "Совершенствование, сначала Огненный шок (Warcraft Tavern)"
L["rm.era.shaman.enhancement.warcrafttavern.Description"] = "Совершенствование по Warcraft Tavern — альтернатива рекомендуемой встроенной ротации «Совершенствование», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Оружие неистовства ветра, как только вы его изучите, Удар бури, Огненный шок перед любым шоком прямого урона, затем Земной шок, пока ваша угроза невелика, или Ледяной шок в группе, когда она высока; Тотем магмы и Цепная молния против групп врагов. Те же тотемы и напоминания, что и в рекомендуемой встроенной ротации."
L["rm.era.shaman.restoration.Name"] = "Исцеление"
L["rm.era.shaman.restoration.Description"] = "Исцеление с 10 уровня (больше всего очков в «Исцелении»); составлено по Icy Veins и Wowhead. На вашей дружественной цели: Волна исцеления под Природной стремительностью, Природная стремительность ниже 30%, Малая волна исцеления ниже 40%, Выведение яда или Излечение болезни, Цепное исцеление, когда у трёх членов группы рядом с вами меньше 85% здоровья, иначе Волна исцеления ниже 90%. С врагом, с которым вы сражаетесь: прерывание Земным шоком, Цепная молния против групп, Огненный шок, Молния с дистанции, ближний бой. Напоминания: Щит молний и Оружие камнедробителя в одиночной игре, Тотем прилива маны в группе, Тотем источника маны, Тотем силы земли, Опаляющий тотем. Кого лечить, понижение ранга заклинаний и Тотем трепета или очищающие тотемы остаются за вами; поддержание Пути исцеления на танке есть в списке, но выключено."
L["rm.era.shaman.restoration.warcrafttavern.Name"] = "Исцеление, сначала Цепное исцеление (Warcraft Tavern)"
L["rm.era.shaman.restoration.warcrafttavern.Description"] = "Исцеление по Warcraft Tavern — альтернатива рекомендуемой встроенной ротации «Исцеление», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Цепное исцеление — основное лечение для любого, у кого меньше 90% здоровья, а Малая волна исцеления — для того, кто вот-вот умрёт; Волна исцеления — только для назначенного лекаря танка с Путём исцеления (есть в списке, но выключена). Те же снятие эффектов, урон по врагам и напоминания о тотемах, что и в рекомендуемой встроенной ротации."
L["rm.forever.shaman.elemental.Name"] = "Элементаль"
L["rm.forever.shaman.elemental.Description"] = "Стихии в дальнем бою, когда «Стихии» — ваша основная ветка талантов с 21 очком (уровень Выброса лавы), по Icy Veins (до этого встроенная ротация «Совершенствование» играет гибрид ближнего боя, который рекомендуют все руководства). Начинает бой Молнией (против группы врагов — Цепной молнией), в движении применяет только мгновенные заклинания, использует Кольцо огня и Цепную молнию при трёх и более врагах, поддерживает Огненный шок, Выброс лавы по готовности, Удар бури и Земной шок, если вы знаете Удар бури, Кольцо огня при Ясности мысли в группах, затем Молния. Напоминания: щит, чары на оружие, Опаляющий тотем или Тотем магмы, групповые тотемы, Покорение стихий, прерывание. В Forever здоровье и мана скрыты от аддонов, поэтому лечение себя и паузы для восполнения маны выбираете вы. За вами остаются: кайт с Тотемом оков земли, Ледяной шок, Развеяние магии и прочие тотемы."
L["rm.forever.shaman.enhancement.Name"] = "Совершенствование (Icy Veins)"
L["rm.forever.shaman.enhancement.Description"] = "Совершенствование в ближнем бою с 1 по 60 уровень; также используется по умолчанию для любого шамана до Выброса лавы или Тотема прилива маны. Начинает бой Молнией с дистанции, затем Удар бури по готовности, мгновенная Молния при пяти наложениях Оружия Водоворота, Кольцо огня (при установленном тотеме огня) и Огненный шок при трёх и более врагах, Земной шок под отрицательный эффект Удара бури, Огненный шок в группах и Земной шок по готовности; Молния заполняет паузу, пока цель вне досягаемости. В Forever здоровье и мана скрыты от аддонов, поэтому лечение себя и паузы для восполнения маны выбираете вы (встроенная ротация Wowhead вместо этого экономит ману). Напоминания: чары на оружие (Оружие неистовства ветра, иначе Оружие языка пламени, иначе Оружие Камнедробителя), Водный щит или Щит молний, прерывание Земным шоком, Опаляющий тотем или Тотем магмы, групповые тотемы, Ярость предсказателя, Тотем каменного когтя. За вами остаются: наборы тотемов, Ледяной шок, Развеяние магии и прочие тотемы."
L["rm.forever.shaman.enhancement.wowhead.Name"] = "Совершенствование, экономия маны (Wowhead)"
L["rm.forever.shaman.enhancement.wowhead.Description"] = "Экономное по мане Совершенствование от Wowhead и Mobalytics: основную работу делает автоатака, Удар бури — только пока не действует восполнение маны от Улучшенного удара бури, без Земного шока в ротации (шоки — для начала боя и прерывания), а в группе или против нескольких врагов — Опаляющий тотем и Кольцо огня по готовности. Те же напоминания о чарах на оружие, щите и прерывании, что и во встроенной ротации Icy Veins. Выбирайте её вместо той встроенной ротации, если вам не хватает маны. Альтернатива рекомендуемой встроенной ротации «Совершенствование», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет."
L["rm.forever.shaman.restoration.Name"] = "Исцеление"
L["rm.forever.shaman.restoration.Description"] = "Лечение, когда «Исцеление» — ваша основная ветка талантов с 16 очками (уровень Тотема прилива маны), по Icy Veins. С дружественной целью: мгновенная Волна исцеления после Природной стремительности, Выведение яда и Излечение болезни, Быстрина на цель без неё, Цепное исцеление в группе, Волна исцеления. Кого лечить, вы выбираете, взяв его в цель; в Forever здоровье и мана скрыты от аддонов, поэтому момент применения Природной стремительности и Малой волны исцеления выбираете вы. С враждебной целью, когда лечить некого: Кольцо огня и Цепная молния против групп врагов, Удар бури и Земной шок, если вы знаете Удар бури, Огненный шок по элитным противникам и боссам, Молния, затем ближний бой. Напоминания: Водный щит, прерывание Земным шоком, Тотем прилива маны и тотемы с групповыми эффектами. За вами остаются: понижение ранга, прочие тотемы, Развеяние магии и Призрачный волк."
L["rm.mop.shaman.elemental.Name"] = "Рекомендуемая"
L["rm.mop.shaman.elemental.Description"] = "Рекомендуется для «Стихий» с 10 уровня; выбирается при специализации «Стихии». Порядок Wowhead: Молния для начала боя (Выброс лавы при Освобожденной ярости), Высвободить чары стихий при Освобожденной ярости, Огненный шок, когда его нет или он вот-вот истечёт на цели, которая проживёт достаточно долго, Выброс лавы по Огненному шоку (и при каждой Волне лавы), Удар духов стихии, Земной шок при шести зарядах Щита молний, пока Огненному шоку осталось 6 секунд, Цепная молния против двух врагов, Молния. Когда с вами сражаются четыре и более врага: Тотем магмы в ближнем бою, бесплатные Выбросы лавы, Поток лавы во время Перерождения, Цепная молния. В движении показывает только мгновенные заклинания. Напоминания: Щит молний, Оружие языка пламени, Опаляющий тотем, Тотем элементаля огня против элитных противников и боссов, Покорение стихий, Перерождение после Выброса лавы, Стремительность предков, Тотем порыва бури и Жажда крови в группе, Пронизывающий ветер, Гром и молния ради маны, Ярость шамана и Астральный сдвиг при низком здоровье. Землетрясение и Тотем элементаля земли есть в списке, но выключены. За вами остаются: Благосклонность предков, Огненный шок на дополнительных целях и где стоять."
L["rm.mop.shaman.enhancement.Name"] = "Рекомендуемая"
L["rm.mop.shaman.enhancement.Description"] = "Рекомендуется для «Совершенствования» с 10 уровня; выбирается при специализации «Совершенствование». Порядок Wowhead: Высвободить чары стихий, пока вы сближаетесь с целью, затем Высвободить чары стихий при Освобожденной ярости, Удар духов стихии и Молния при пяти наложениях Оружия Водоворота (или вплетённая при трёх, когда до следующего удара оружием больше секунды), Свирепость бури во время Перерождения, Удар бури (до 26 уровня — Стихийный удар), Вскипание лавы, Огненный шок под Высвободить чары огня, Высвободить чары стихий, Земной шок. Когда с вами сражаются два и более врага: Цепная молния вместо Молнии, Вскипание лавы для распространения Огненного шока, Кольцо огня от четырёх, Тотем магмы от шести. Напоминания: Щит молний, Оружие неистовства ветра на правой руке и Оружие языка пламени на левой, Опаляющий тотем, Тотем элементаля огня, Дух дикого волка, Перерождение после Удара бури, Покорение стихий, Стремительность предков, Тотем порыва бури и Жажда крови в группе, Пронизывающий ветер, Ярость шамана и Астральный сдвиг при низком здоровье. Тотем элементаля земли есть в списке, но выключен."
L["rm.mop.shaman.enhancement.icyveins.Name"] = "Сначала Вскипание лавы (Icy Veins)"
L["rm.mop.shaman.enhancement.icyveins.Description"] = "По умолчанию выключена; переключение то же, что и у рекомендуемой встроенной ротации «Совершенствование», поэтому, чтобы использовать её, включите её и выключите ту. Порядок Icy Veins: Удар бури, затем Вскипание лавы перед тратой Оружия Водоворота, Молния при пяти наложениях или от трёх, если она долетит до следующего удара оружием, Высвободить чары стихий, затем Огненный шок, Земной шок. Против четырёх и более врагов распространяет Огненный шок Вскипанием лавы и использует Кольцо огня; против групп Цепная молния заменяет Молнию. Ярость шамана предлагается в бою по готовности; остальные напоминания — как в рекомендуемой встроенной ротации."
L["rm.mop.shaman.enhancement.simulator.Name"] = "Вплетение на любом наложении (симулятор)"
L["rm.mop.shaman.enhancement.simulator.Description"] = "По умолчанию выключена; переключение то же, что и у рекомендуемой встроенной ротации «Совершенствование», поэтому, чтобы использовать её, включите её и выключите ту. Список симулятора для тех, кто вписывает заклинания между ударами оружием: Молния, Удар духов стихии или Цепная молния при любом числе наложений Оружия Водоворота, если применение закончится до следующего удара правой рукой, Высвободить чары стихий также всякий раз, когда нет Огненного шока, и Земной шок только ниже двух наложений. Напоминания — как в рекомендуемой встроенной ротации."
L["rm.mop.shaman.restoration.Name"] = "Рекомендуемая"
L["rm.mop.shaman.restoration.Description"] = "Рекомендуется для «Исцеления» с 10 уровня; выбирается при специализации «Исцеление». Лечит вашу дружественную цель (Rotation Master не может выбирать, кого лечить): Великая волна исцеления под Стремительностью предков, Исцеляющий всплеск ниже 35%, Очищение духа от магии или проклятий, Высвободить чары стихий, затем Целительный ливень, когда ранены трое союзников рядом, Быстрина, Цепное исцеление при уроне по группе, Великая волна исцеления ниже 60%, Волна исцеления ниже 90%. С атакуемой целью вместо этого наносит урон (Огненный шок, Выброс лавы, Удар духов стихии, Молния). Напоминания: Водный щит, Оружие жизни земли, Щит земли на ваш фокус, Тотем исцеляющего потока, когда кто-то ранен, Тотем прилива маны, Тотем целительного прилива при сильном уроне по группе, Покорение стихий или Наставления предков, Стремительность предков на цель с малым здоровьем, Благосклонность предков в движении, Жажда крови, Пронизывающий ветер. Перерождение и Тотем духовной связи есть в списке, но выключены: используйте их, когда рейд вам их назначает."
L["rm.mop.shaman.restoration.hekili.Name"] = "Ступени здоровья (Hekili)"
L["rm.mop.shaman.restoration.hekili.Description"] = "По умолчанию выключена; переключение то же, что и у рекомендуемой встроенной ротации «Исцеление», поэтому, чтобы использовать её, включите её и выключите ту. Список Hekili поддерживает Щит земли и Быстрину на вашей цели, а Тотем исцеляющего потока и Целительный ливень — всякий раз, когда их нет, затем лечит по среднему здоровью вашей группы в пределах 40 м: Цепное исцеление ниже 80%, Волна исцеления на цель ниже 70%, Великая волна исцеления ниже 60%, Исцеляющий всплеск ниже 40%, с Тотемом целительного прилива, Наставлениями предков и Тотемом прилива маны на тех же ступенях. Атакуемая цель получает урон и Земной шок."
L["rm.mop.shaman.unspecialized.Name"] = "Без специализации"
L["rm.mop.shaman.unspecialized.Description"] = "Для уровней 1–9 и любого шамана, который ещё не выбрал специализацию; как только вы её выберете, в силу вступает встроенная ротация специализации. Молния для начала боя с дистанции, Исцеляющий всплеск, когда у вас мало здоровья и вы одни, Стихийный удар, Земной шок и Молния вне зоны ближнего боя. Поддерживает Щит молний."
L["rm.retail.shaman.elemental.Name"] = "Боевой помощник Blizzard"
L["rm.retail.shaman.elemental.Description"] = "Рекомендуется для специализации «Стихии» в Midnight. В бою игра теперь скрывает от аддонов Огненный шок, ваши положительные эффекты, энергию Водоворота, время восстановления и здоровье, поэтому эта ротация показывает собственное предложение Боевого помощника Blizzard (ротация одной кнопкой) и приостанавливается, пока вы применяете заклинание или у вас нет враждебной цели. Напоминания о том, что оно упускает: Перерождение, Элементаль огня или Элементаль бури и Природная стремительность в бою, Благосклонность предков в движении, Щит молний и Небесная ярость между боями (предложение Blizzard поддерживает ваши чары на оружии и щите), Пронизывающий ветер против прерываемого заклинания (он загорается только там, где игра позволяет прочитать заклинание), Астральный сдвиг по готовности в бою (здоровье на Retail скрыто, поэтому момент его применения — на ваше усмотрение)."
L["rm.retail.shaman.elemental.icyveins.Name"] = "Для справки (Icy Veins)"
L["rm.retail.shaman.elemental.icyveins.Description"] = "Только для справки, по умолчанию выключена: порядок Icy Veins и SimulationCraft читает Огненный шок, Властелина стихий и Хранителя бурь, которые Midnight скрывает в бою; энергия Водоворота на Retail скрыта, поэтому расходующие заклинания применяются по стоимости, а не при почти полной энергии Водоворота. Хранитель бурь и Выброс лавы перед боем. Против трёх и более врагов, вступивших в бой: Хранитель бурь, Стремительность предков, Огненный шок, Цепная молния с Хранителем бурь, Удар духов стихий, Землетрясение, Выброс лавы при Волне лавы, Буря, Цепная молния. Иначе Хранитель бурь, Стремительность предков, Огненный шок и Гальваническое пламя в последние 30% длительности вне Властелина стихий, Выброс лавы, чтобы его запустить, Буря и Молния с Хранителем бурь во время него, Удар духов стихий или Земной шок во время него, Гальваническое пламя, Буря, Огненный шок или Ледяной шок в движении, Удар духов стихий или Земной шок, когда хватает ресурса, Молния. Напоминания: Перерождение после использования Хранителя бурь, элементали, Благосклонность предков и общие напоминания."
L["rm.retail.shaman.enhancement.Name"] = "Боевой помощник Blizzard"
L["rm.retail.shaman.enhancement.Description"] = "Рекомендуется для специализации «Совершенствование» в Midnight. Показывает предложение Боевого помощника Blizzard (оно тратит заряды Оружия Водоворота, поддерживает Огненный шок и берёт на себя Пульсирующий тотем и Раскол) и приостанавливается, пока вы применяете заклинание или у вас нет враждебной цели. Напоминания о том, что оно упускает: Перерождение, Ветра рока и Дух дикого зверя в бою, Щит молний и Небесная ярость между боями (предложение Blizzard поддерживает Оружие неистовства ветра), Пронизывающий ветер, Астральный сдвиг."
L["rm.retail.shaman.enhancement.stormbringer.Name"] = "Вестник шторма, для справки (SimulationCraft)"
L["rm.retail.shaman.enhancement.stormbringer.Description"] = "Только для справки, по умолчанию выключена: список SimulationCraft для Вестника шторма (Icy Veins и Wowhead согласны) читает Огненный шок, Сокрушающую молнию, Хлещущее пламя и таймеры восстановления, которые Midnight скрывает в бою. Против трёх и более врагов, вступивших в бой: Сокрушающая молния ради её эффекта, Буря при 10 зарядах Оружия Водоворота, Цепная молния при 9, Сокрушающая молния, Вскипание лавы, Раскол. Затем Первозданная буря при 9, Гальваническое пламя или Огненный шок, если Огненного шока нет, Раскол, Сокрушающая молния ради её эффекта, Вскипание лавы ради Хлещущего пламени, Удар ветра, Буря или Молния при 10 (при 8, если Гальваническое пламя или Сокрушающая молния почти готовы), Удар бури при двух зарядах, Вскипание лавы, Удар бури, Гальваническое пламя, Сокрушающая молния, Молния при 5, Огненный шок. Напоминания: Ветра рока, Перерождение вне Ветров рока, Дух дикого зверя и общие напоминания."
L["rm.retail.shaman.enhancement.totemic.Name"] = "Тотемист, для справки (SimulationCraft)"
L["rm.retail.shaman.enhancement.totemic.Description"] = "Только для справки, по умолчанию выключена: список SimulationCraft для Тотемиста читает Огненный шок, Горячую руку, Бушующий ураган, Сокрушающую молнию и Ветра рока, которые Midnight скрывает в бою. Против трёх и более врагов, вступивших в бой: Сокрушающая молния, Цепная молния при 5 зарядах Оружия Водоворота. Затем Гальваническое пламя или Огненный шок, если Огненного шока нет, Пульсирующий тотем, Раскол, Вскипание лавы с Горячей рукой или Бушующим ураганом, Сокрушающая молния ради её эффекта, Первозданная буря при 10, Удар ветра, Сокрушающая молния и Удар бури во время Ветров рока, Молния при 5, Сокрушающая молния, Вскипание лавы, Удар бури, Гальваническое пламя, Огненный шок. Те же напоминания, что и в справочной ротации Вестника шторма."
L["rm.retail.shaman.initial.Name"] = "Боевой помощник Blizzard"
L["rm.retail.shaman.initial.Description"] = "Рекомендуется до выбора специализации (пока игра сообщает начальную специализацию шамана). Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — общие напоминания всех встроенных ротаций шамана, каждое — как только вы знаете соответствующее заклинание. Когда на 10 уровне вы выбираете специализацию, её встроенные ротации вступают в силу."
L["rm.retail.shaman.restoration.Name"] = "Icy Veins"
L["rm.retail.shaman.restoration.Description"] = "«Исцеление» в Midnight, для справки: Боевой помощник Blizzard не охватывает лекарей, игра скрывает здоровье всех в бою, а Rotation Master выбирает заклинание, а не цель, поэтому эта ротация упорядочивает ваши лечащие способности по готовности на любой выбранной вами цели, а решать, кого лечить, оставляет вам. С дружественной целью: Тотем исцеляющего потока, Высвободить чары жизни, Целительный ливень в группе, Пульсирующий тотем, Быстрина, Цепное исцеление в группе, Волна исцеления. С враждебной целью: Огненный шок, если его нет, Выброс лавы, Молния. Напоминания: Водный щит, Щит земли на дружественную цель и Небесная ярость между боями; Природная стремительность в бою; Тотем целительного прилива и Тотем духовной связи в бою в группе; Пронизывающий ветер; Астральный сдвиг."
L["rm.sod.shaman.elemental.Name"] = "Стихии (SoD)"
L["rm.sod.shaman.elemental.Description"] = "Стихии для сезона открытий с 10 уровня (больше всего очков в «Стихиях»); составлено по симулятор (6-я фаза), Wowhead и Icy Veins. Земной шок прерывает. В движении: Огненный шок, Земной шок при восьми зарядах Щита молний, Выброс лавы или Цепная молния при срабатывании Волны силы. Против трёх и более врагов: Огненный шок, Цепная молния, Кольцо огня, Выброс лавы, Земной шок при восьми зарядах, Тотем магмы. Затем Выброс лавы при Волне силы, Огненный шок постоянно поддерживается, Выброс лавы, пока действует ваш Огненный шок, Земной шок при восьми зарядах, Цепная молния против двух врагов, Молния. Напоминания: Оружие языка пламени ради Горения, Щит молний, Щит земли на себя, Дух вожака стаи, Дух дикого волка, Ярость шамана, Покорение стихий, тотемы. Аксессуары, Проецирование тотемов, рассеивание и развеивание остаются за вами."
L["rm.sod.shaman.enhancement.Name"] = "Совершенствование (SoD)"
L["rm.sod.shaman.enhancement.Description"] = "Сезон открытий, уровни 1–60, руны используются по мере того, как вы их гравируете, два оружия или двуручное, а также любой шаман сезона открытий, которому не подходит другая встроенная ротация; составлено по симулятор (6-я фаза), Icy Veins и Wowhead. Начинает бой Огненным шоком; Земной шок прерывает. Против трёх и более врагов: Тотем магмы, Кольцо огня от тотема огня, Цепная молния при четырёх наложениях Оружия Водоворота, Огненный шок. Затем Выброс лавы при пяти наложениях Оружия Водоворота, Удар бури, Вскипание лавы, Молния при пяти наложениях, Огненный шок, если он успеет отработать, Земной шок, Всплеск лавы, Молния с дистанции. Напоминания: Оружие неистовства ветра (до него — Оружие камнедробителя), Оружие языка пламени на оружии в левой руке при Вскипании лавы (иначе Оружие неистовства ветра; никогда на щите; строка Icy Veins с неистовством ветра на обоих оружиях есть в списке, но выключена), Водный щит или Щит молний, Дух вожака стаи, Дух дикого волка, Ярость шамана при мане ниже 65%, тотемы, Наставления предков. Проецирование тотемов, рассеивание и развеивание остаются за вами."
L["rm.sod.shaman.restoration.Name"] = "Исцеление (SoD)"
L["rm.sod.shaman.restoration.Description"] = "Исцеление для сезона открытий с 10 уровня (больше всего очков в «Исцелении»); составлено по Icy Veins и Wowhead. На вашей дружественной цели: Быстрина, затем Малая волна исцеления ниже 40%, Выведение яда или Излечение болезни, Целительный ливень, когда у трёх членов группы рядом с вами меньше 85% здоровья, Цепное исцеление, когда таких двое (сразу при срабатывании Волны силы), Быстрина ниже 95% ради Приливных волн, Волна исцеления ниже 90%. Сражается с врагом, если он в цели. Напоминания: Водный щит (до него — Щит молний), Щит земли на вашу дружественную цель или на себя, Ярость шамана, Тотем прилива маны, Тотем источника маны и Тотем силы земли. Кого лечить и Тотем трепета или очищающие тотемы остаются за вами."
L["rm.sod.shaman.tank.Name"] = "Танк (SoD, Путь земли)"
L["rm.sod.shaman.tank.Description"] = "Танк для сезона открытий; выбирается, когда выгравирован Путь земли; составлено по Icy Veins, Wowhead, симулятор и Warcraft Tavern. Начинает бой Огненным шоком. Земной шок провоцирует цель в ближнем бою, которая не атакует вас, и прерывает. Против двух и более врагов: Всплеск лавы, Огненный шок, Цепная молния при пяти наложениях Оружия Водоворота или при Волне силы, Кольцо огня при пяти наложениях. Затем Огненный шок постоянно поддерживается, Выброс лавы при Волне силы или пока действует Огненный шок, Удар бури, Земной шок, Молния при пяти наложениях, Всплеск лавы, Ледяной шок. Напоминания: Оружие камнедробителя, Щит молний, Дух вожака стаи на себя, Дух дикого волка, Ярость шамана, Опаляющий тотем или Тотем магмы и групповые тотемы."
L["rm.tbc.shaman.elemental.icyveins.Name"] = "Стихии (Icy Veins и симулятор)"
L["rm.tbc.shaman.elemental.icyveins.Description"] = "Заклинатель для ветки талантов «Стихии». Молния — основное заклинание; Цепная молния — вместе с Покорением стихий, при Ясности мысли, если у вас не меньше 40% маны, или свободно при мане выше 80%; Огненный шок — только в движении; Земной шок прерывает; Кольцо огня, Цепная молния и Тотем магмы — против групп врагов. Перед шагом с Цепной молнией цель в ближнем бою оставляется автоатаке ради экономии маны. Напоминания: Водный щит или Щит молний, чары на оружие, Тотем гнева (или Опаляющий тотем в долгих боях), Тотем гнева воздуха, Тотем источника маны, Зов тотема после боя, Покорение стихий и Кровожадность/Героизм."
L["rm.tbc.shaman.elemental.nextaction.Name"] = "Стихии (NextActionTBC)"
L["rm.tbc.shaman.elemental.nextaction.Description"] = "«Стихии» по NextActionTBC — альтернатива рекомендуемой встроенной ротации «Стихии» от Icy Veins, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Поддерживает Огненный шок на цели, Цепную молнию — только против двух и более врагов при мане выше 30%, иначе Молния. Напоминает о Щите молний, чарах на оружие, Покорении стихий и Жажде крови/Героизме; тотемы ставятся вручную."
L["rm.tbc.shaman.elemental.wowhead.Name"] = "Стихии (Wowhead)"
L["rm.tbc.shaman.elemental.wowhead.Description"] = "«Стихии» по Wowhead — альтернатива рекомендуемой встроенной ротации «Стихии» от Icy Veins, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. На 70 уровне Цепная молния по готовности, а между ними Молнии (при прокачке — только с Покорением стихий или Ясностью мысли), Огненный шок только в движении, Земной шок, чтобы добить цель, которая умрёт раньше, чем долетит заклинание. Те же напоминания о тотемах, щите и способностях с восстановлением, что и в варианте Icy Veins."
L["rm.tbc.shaman.enhancement.icyveins.Name"] = "Совершенствование (Icy Veins)"
L["rm.tbc.shaman.enhancement.icyveins.Description"] = "Совершенствование в ближнем бою с 1 по 70 уровень; также используется по умолчанию для любого шамана, которому не подходит другая встроенная ротация. Начинает бой Молнией с дистанции, прерывает Земным шоком, ставит Тотем кольца огня и Тотем магмы при трёх и более врагах рядом, затем Удар бури, Земной шок, пока на цели висит отрицательный эффект Удара бури, Огненный шок на цель, которая проживёт достаточно долго, Земной шок по готовности и Молния, пока цель вне досягаемости. Отдельные напоминания: чары на оружие, Водный щит или Щит молний, Тотем силы земли, Тотем неистовства ветра (в группе) или Тотем легкости воздуха (в одиночку), Опаляющий тотем в долгих боях, тотемы воды, Ярость шамана, Кровожадность/Героизм на боссах, Тотем каменного когтя и Тотем элементаля земли в одиночной игре. Тотем элементаля огня — необязательный шаг, по умолчанию выключенный. Расстановка тотемов, Призрачный волк и лечение остаются за вами."
L["rm.tbc.shaman.enhancement.simulator.Name"] = "Совершенствование (Wowhead и симулятор)"
L["rm.tbc.shaman.enhancement.simulator.Description"] = "Рейдовая модель 70 уровня для твиста тотемов — альтернатива рекомендуемой встроенной ротации «Совершенствование» от Icy Veins, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Удар бури, вплетённый Тотем кольца огня, Огненный шок всякий раз, когда он спал, и Земной шок как основной шок; Молния — только когда цель вне досягаемости. Напоминания чередуют (твистят) Тотем неистовства ветра и Тотем легкости воздуха, поддерживают Опаляющий тотем, предлагают Ярость шамана, когда мана на исходе, и разделяют с вариантом Icy Veins поддержание чар на оружии, щита и тотемов."
L["rm.tbc.shaman.restoration.Name"] = "Исцеление"
L["rm.tbc.shaman.restoration.Description"] = "Лечение для ветки талантов «Исцеление» на дружественной цели (или на себе, если цели нет): Природная стремительность и Волна исцеления или Слабая волна исцеления в экстренных случаях, Выведение яда и Излечение болезни, Щит земли на фокусе, Цепное исцеление, когда ранены трое союзников рядом, в остальных случаях Волна исцеления. С враждебной целью переключается на Огненный шок и Молнию для одиночной игры. Напоминания: Водный щит, Щит земли на фокусе (назначьте танка фокусом), Тотем прилива маны, Тотем источника маны и Тотем силы земли в группе, Кровожадность/Героизм. Кого лечить и каким рангом — решаете вы."
